import sys

CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def next_id(current: str) -> str:
    """Increment a base-36 4‑character suffix, return 'ORD-' + result."""
    suffix = list(current)
    for i in range(3, -1, -1):
        pos = CHARS.find(suffix[i])
        if pos == -1:
            raise ValueError(f'Invalid character {suffix[i]!r} in id suffix')
        if pos < 35:
            suffix[i] = CHARS[pos + 1]
            return 'ORD-' + ''.join(suffix)
        suffix[i] = '0'
    raise OverflowError('Cannot increment — all four positions exhausted')


def last_id_from(path: str) -> str:
    """Read the last non‑empty id line from *path*."""
    with open(path) as f:
        last = None
        for line in f:
            line = line.strip()
            if line:
                last = line
    if last is None:
        raise ValueError(f'No ids found in {path}')
    return last.split('-', 1)[1]  # e.g. '243G'


def main() -> None:
    current = last_id_from('ids.txt')
    print(next_id(current))


if __name__ == '__main__':
    main()
