#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next id."""

from __future__ import annotations

import sys


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base-36 string of the given width."""
    digits: list[str] = []
    while n > 0:
        n, rem = divmod(n, 36)
        digits.append("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[rem])
    s = "".join(reversed(digits))
    return s.rjust(width, "0")


def from_base36(s: str) -> int:
    """Parse a base-36 string to an integer."""
    return int(s, 36)


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    suffix = last_id.removeprefix("ORD-")

    n = from_base36(suffix)
    n += 1
    print(f"ORD-{to_base36(n, 4)}")


if __name__ == "__main__":
    main()

