#!/usr/bin/env python3
"""Read events.jsonl, remove duplicates sharing an event_id, write deduped.jsonl."""

import json


def main() -> None:
    seen: set[str] = set()
    unique_lines: list[str] = []

    with open("events.jsonl") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                continue
            event = json.loads(line)
            eid = event["event_id"]
            if eid in seen:
                continue
            seen.add(eid)
            unique_lines.append(line)

    with open("deduped.jsonl", "w") as f:
        for line in unique_lines:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

