import os
import re


def report_order(name: str) -> tuple[int, str]:
    """Sort key: extract numeric part for natural ordering, fall back to string."""
    match = re.search(r'(\d+)', name)
    num = int(match.group(1)) if match else 0
    return (num, name)


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(__file__), 'reports')
    if not os.path.isdir(reports_dir):
        return  # no reports yet

    names = sorted(
        (n for n in os.listdir(reports_dir) if os.path.isfile(os.path.join(reports_dir, n))),
        key=report_order,
    )
    for name in names:
        print(name)


if __name__ == '__main__':
    main()

