import os
import re

REPORTS_DIR = "reports"

files = os.listdir(REPORTS_DIR)

# Extract the numeric part from "report-<n>.txt" and sort by it
def sort_key(name: str) -> int:
    match = re.match(r"report-(\d+)\.txt", name)
    if match:
        return int(match.group(1))
    return 0  # fallback for unexpected names

sorted_files = sorted(files, key=sort_key)

for f in sorted_files:
    print(f)

