#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
import os
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f'Usage: python {sys.argv[0]} AS_OF', file=sys.stderr)
        sys.exit(1)

    try:
        as_of_ts = int(sys.argv[1])
    except ValueError:
        print(f'Error: AS_OF must be an integer Unix timestamp, got {sys.argv[1]!r}', file=sys.stderr)
        sys.exit(1)

    as_of = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff = datetime.fromtimestamp(as_of_ts - 7 * 86400, tz=timezone.utc)

    app_path = os.path.join(os.path.dirname(__file__) or '.', 'app.log')
    archive_path = os.path.join(os.path.dirname(__file__) or '.', 'archive.log')

    if not os.path.exists(app_path):
        print('app.log not found, nothing to do.', file=sys.stderr)
        sys.exit(0)

    with open(app_path, 'r') as f:
        lines = f.readlines()

    old_entries: list[str] = []
    kept_entries: list[str] = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt < cutoff:
            old_entries.append(line)
        else:
            kept_entries.append(line)

    # Append old entries to archive.log (preserving order)
    if old_entries:
        with open(archive_path, 'a') as f:
            f.writelines(old_entries)

    # Rewrite app.log with kept entries (preserving order)
    with open(app_path, 'w') as f:
        f.writelines(kept_entries)


if __name__ == '__main__':
    main()

